examples.das:
// generated by c2das - regenerate, never edit
options gen2
options indenting = 4
options solid_context
options stack = 8388608
options strict_aliasing = false
require c_runtime/cstr
require c_runtime/printf

[init]
def private c2das_dialect {
    c_long_bits = 64
}

def private fib__fib_rec(n : int) : int {
    return n < 2 ? n : fib__fib_rec(n - 1) + fib__fib_rec(n - 2)
}

def private fib__fib_loop(n : int) : int64 {
    var a : int64 = 0l
    var b : int64 = 1l
    for (i in range(n)) {
        let t : int64 = a + b
        a = b
        b = t
    }
    return a
}

def c_main : int {
    {
        var n : int = 0
        while (n <= 20) {
            printf(cstr("fib(%d) = %d = %lld\n"), n, fib__fib_rec(n), fib__fib_loop(n))
            n += 5
        }
    }
    return 0
}

[export]
def main : int {
    return c_main()
}

examples.c:
// Arrays and nested loops: the primes below 100.
#include <stdio.h>
#include <string.h>

#define LIMIT 100

int main(void)
{
    char composite[LIMIT];
    memset(composite, 0, sizeof composite);
    int count = 0;
    for (int i = 2; i < LIMIT; i++) {
        if (composite[i])
            continue;
        printf("%d ", i);
        count++;
        for (int j = i * i; j < LIMIT; j += i)
            composite[j] = 1;
    }
    printf("\n%d primes below %d\n", count, LIMIT);
    return 0;
}

