examples.das:
// generated by c2das - regenerate, never edit
options gen2
options indenting = 4
options solid_context
options stack = 8388608
options strict_aliasing = false
require c_runtime/c_function
require c_runtime/c_switch
require c_runtime/cstr
require c_runtime/printf

[init]
def private c2das_dialect {
    c_long_bits = 64
}

enum anon_0 {
    SET
    MOV
    ADD
    SUB
    MUL
    DEC
    JNZ
    PRINT
    NOP
    HALT
}

var private main_code : int[19] = fixed_array(int(anon_0.SET), 0, 1, int(anon_0.SET), 1, 5, int(anon_0.PRINT), 1, int(anon_0.MUL), 0, 1, int(anon_0.DEC), 1,
        int(anon_0.JNZ), 1, 6, int(anon_0.NOP), int(anon_0.HALT), 0)

[c_function]
def private switch_vm__run(var code : int?) : int {
    var r : int[4] = fixed_array(0, 0, 0, 0)
    var pc : int = 0
    while (true) {
        let _t0 = pc
        pc++
        let op : int = code[_t0]
        c_switch(op) {
            case(0) {
                r[code[pc]] = code[pc + 1]
                pc += 2
                break
            }
            case(1) {
                r[code[pc]] = r[code[pc + 1]]
                pc += 2
                break
            }
            case(2) {
                r[code[pc]] += r[code[pc + 1]]
                pc += 2
                break
            }
            case(3) {
                r[code[pc]] -= r[code[pc + 1]]
                pc += 2
                break
            }
            case(4) {
                r[code[pc]] *= r[code[pc + 1]]
                pc += 2
                break
            }
            case(5) {
                r[code[pc]]--
                pc += 1
                break
            }
            case(6) {
                pc = r[code[pc]] != 0 ? code[pc + 1] : pc + 2
                break
            }
            case(7) {
                printf(cstr("r%d = %d\n"), code[pc], r[code[pc]])
                pc += 1
                break
            }
            case(8) {
                break
            }
            case(9) {
                return r[code[pc]]
            }
            case(_) {
                return -1
            }
        }
    }
    return 0
}

[c_function]
def c_main : int {
    // r0 = 1, r1 = 5; loop: print r1; r0 *= r1; r1--; if r1 goto loop; halt with r0 = 5!
    printf(cstr("5! = %d\n"), switch_vm__run(addr(main_code[0])))
    return 0
}

[export]
def main : int {
    return c_main()
}

examples.c:
// Structs, pointers and the heap: a linked list built, reversed and freed.
#include <stdio.h>
#include <stdlib.h>

struct node {
    int value;
    struct node *next;
};

static struct node *push(struct node *head, int value)
{
    struct node *n = malloc(sizeof *n);
    n->value = value;
    n->next = head;
    return n;
}

static struct node *reverse(struct node *head)
{
    struct node *prev = NULL;
    while (head) {
        struct node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

int main(void)
{
    struct node *list = NULL;
    for (int i = 1; i <= 5; i++)
        list = push(list, i * i);
    list = reverse(list);
    for (struct node *p = list; p; p = p->next)
        printf("%d%s", p->value, p->next ? " -> " : "\n");
    while (list) {
        struct node *next = list->next;
        free(list);
        list = next;
    }
    return 0;
}

