examples.das:
// generated by c2das - regenerate, never edit
options gen2
options indenting = 4
options solid_context
options stack = 8388608
options strict_aliasing = false
require c_runtime/c_function
require c_runtime/cstr
require c_runtime/printf
require crt

[init]
def private c2das_dialect {
    c_long_bits = 64
}

struct node {
    value : int
    next : node?
}

[init]
def private c2das_layout_check {
    static_assert(typeinfo sizeof(type<node>) == 16 && typeinfo alignof(type<node>) == 8, "node: clang lays it out as size 16, align 8")
    static_assert(typeinfo offsetof < value > (type<node>) == 0, "node.value: clang puts it at 0")
    static_assert(typeinfo offsetof < next > (type<node>) == 8, "node.next: clang puts it at 8")
}

[c_function]
def private list__push(var head : node?; value : int) : node? {
    var n : node? = reinterpret<node?>(crt::malloc(uint64(typeinfo sizeof(type<node>))))
    n.value = value
    n.next = head
    return n
}

def private list__reverse(var head : node?) : node? {
    var prev : node? = null
    while (head != null) {
        var next : node? = head.next
        head.next = prev
        prev = head
        head = next
    }
    return prev
}

[c_function]
def c_main : int {
    var list : node? = null
    for (i in range(1, 6)) {
        list = list__push(list, i * i)
    }
    list = list__reverse(list)
    {
        var p : node? = list
        while (p != null) {
            printf(cstr("%d%s"), p.value, p.next != null ? cstr(" -> ") : cstr("\n"))
            p = p.next
        }
    }
    while (list != null) {
        var next : node? = list.next
        crt::free(reinterpret<void?>(list))
        list = next
    }
    return 0
}

[export]
def main : int {
    return c_main()
}

examples.c:
// Function-like macros: the --fn-macros knob folds a macro into a [c_macro] def (fold)
// or spells its expansion at every site (expand).
#include <stdio.h>

#define SQUARE(x) ((x) * (x))
#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define CLAMP(v, lo, hi) ((v) < (lo) ? (lo) : (v) > (hi) ? (hi) : (v))

int main(void)
{
    for (int i = -3; i <= 3; i++)
        printf("%d: square %d, max with 0 %d, clamped to [-1, 1] %d\n", i, SQUARE(i), MAX(i, 0), CLAMP(i, -1, 1));
    return 0;
}

