examples.das:
// generated by c2das - regenerate, never edit
options gen2
options indenting = 4
options solid_context
options stack = 8388608
options strict_aliasing = false
require c_runtime/c_macro
require c_runtime/cstr
require c_runtime/printf

[init]
def private c2das_dialect {
    c_long_bits = 64
}

// macros.c:5: #define SQUARE(x) ((x) * (x))
[c_macro]
def private SQUARE(x) => x * x

// macros.c:6: #define MAX(a, b) ((a) > (b) ? (a) : (b))
[c_macro]
def private MAX(a; b) => a > b ? a : b

// macros.c:7: #define CLAMP(v, lo, hi) ((v) < (lo) ? (lo) : (v) > (hi) ? (hi) : (v))
[c_macro]
def private CLAMP(v; lo; hi) => v < lo ? lo : (v > hi ? hi : v)

def c_main : int {
    for (i in range(-3, 4)) {
        printf(cstr("%d: square %d, max with 0 %d, clamped to [-1, 1] %d\n"), i, SQUARE(i), MAX(i, 0), CLAMP(i, -1, 1))
    }
    return 0
}

[export]
def main : int {
    return c_main()
}

examples.c:
// C strings: bytes, pointer walks and the C library, as c2das-re keeps them (uint8, never das strings).
#include <stdio.h>
#include <string.h>
#include <ctype.h>

static void upcase(char *s)
{
    for (; *s; s++)
        *s = (char)toupper((unsigned char)*s);
}

static int count_char(const char *s, char c)
{
    int n = 0;
    while ((s = strchr(s, c)) != NULL) {
        n++;
        s++;
    }
    return n;
}

int main(void)
{
    char text[64];
    strcpy(text, "translated by c2das-re");
    printf("%s has %d bytes and %d 'a's\n", text, (int)strlen(text), count_char(text, 'a'));
    upcase(text);
    printf("%s\n", text);
    return 0;
}

