examples.das:
// generated by c2das - regenerate, never edit
options gen2
options indenting = 4
options solid_context
options stack = 8388608
options strict_aliasing = false
require c_runtime/c_function
require c_runtime/cstr
require c_runtime/printf
require crt

[init]
def private c2das_dialect {
    c_long_bits = 64
}

[c_function]
def private strings__upcase(var s : uint8?) {
    while (*s != 0) {
        *s = uint8(crt::toupper(int(*s)))
        s++
    }
}

[c_function]
def private strings__count_char(var s : uint8?; c : uint8) : int {
    var n : int = 0
    while (true) {
        s = crt::strchr(s, int(c))
        if (!(s != null)) {
            break
        }
        n++
        s++
    }
    return n
}

[c_function]
def c_main : int {
    var text : uint8[64]
    crt::strcpy(addr(text[0]), cstr("translated by c2das-re"))
    printf(cstr("%s has %d bytes and %d 'a's\n"), addr(text[0]), int(crt::strlen(addr(text[0]))), strings__count_char(addr(text[0]), uint8('a')))
    strings__upcase(addr(text[0]))
    printf(cstr("%s\n"), addr(text[0]))
    return 0
}

[export]
def main : int {
    return c_main()
}
